#import "ui.h"
static NSDictionary *hotkeyKinds;
static OSStatus HotkeyHandler(EventHandlerCallRef next,EventRef event,void *user){EventHotKeyID id;GetEventParameter(event,kEventParamDirectObject,typeEventHotKeyID,NULL,sizeof(id),NULL,&id);NSString *kind=hotkeyKinds[@(id.id)];if(kind)Emit(kind,@{});return noErr;}
@implementation ThiefApp (Hotkeys)
- (void)registerHotkeys:(NSDictionary *)bindings {if(!bindings||[bindings isEqual:self.registeredHotkeys])return;static BOOL installed=NO;if(!installed){EventTypeSpec type={kEventClassKeyboard,kEventHotKeyPressed};InstallApplicationEventHandler(&HotkeyHandler,1,&type,NULL,NULL);installed=YES;}if(!self.hotkeyRefs)self.hotkeyRefs=[NSMutableDictionary new];NSMutableDictionary *next=[NSMutableDictionary new],*kinds=[NSMutableDictionary new];static uint32_t index=100;NSString *error=nil;for(NSString *kind in [[bindings allKeys] sortedArrayUsingSelector:@selector(compare:)]){NSDictionary *b=bindings[kind];NSDictionary *old=self.registeredHotkeys[kind];if([b isEqual:old]&&self.hotkeyRefs[kind]){next[kind]=self.hotkeyRefs[kind];continue;}EventHotKeyRef ref=NULL;EventHotKeyID id={'thif',index++};OSStatus result=RegisterEventHotKey([b[@"KeyCode"] unsignedIntValue],[b[@"Modifiers"] unsignedIntValue],id,GetApplicationEventTarget(),0,&ref);if(result!=noErr){error=[NSString stringWithFormat:@"快捷键 %@ 注册失败（%d），请换一个组合。",kind,(int)result];break;}next[kind]=[NSValue valueWithPointer:ref];kinds[@(id.id)]=kind;}
 if(error){for(NSString *kind in next){if(next[kind]!=self.hotkeyRefs[kind])UnregisterEventHotKey([next[kind] pointerValue]);}self.message.textColor=NSColor.systemRedColor;self.message.stringValue=error;if(self.registeredHotkeys){NSMutableDictionary *settings=[self.snapshot[@"Settings"] mutableCopy];settings[@"Hotkeys"]=self.registeredHotkeys;Emit(@"hotkeyRollback",@{@"Settings":settings,@"Query":error});}return;}
 // Preserve handler IDs for unchanged registrations; remove retired IDs only after success.
 NSMutableDictionary *all=[hotkeyKinds mutableCopy]?:[NSMutableDictionary new];for(NSNumber *key in [all.allKeys copy]){NSString *kind=all[key];if(next[kind]!=self.hotkeyRefs[kind])[all removeObjectForKey:key];}[all addEntriesFromDictionary:kinds];for(NSString *kind in self.hotkeyRefs){if(next[kind]!=self.hotkeyRefs[kind])UnregisterEventHotKey([self.hotkeyRefs[kind] pointerValue]);}hotkeyKinds=all;self.hotkeyRefs=next;self.registeredHotkeys=[bindings copy];
}
@end
